"""Strict validation of the version-3 controller request wire format.

Every rule published in PROTOCOL.md is enforced here.  The entry contract is:
invalid input yields exactly {"error":"invalid"} with exit status zero and no
partial results, so validation failures are raised as a single exception type
and handled once at the top level.
"""
import json

MAX_BYTES = 16 * 1024 * 1024
MAX_DEPTH = 64

INT10_12 = 10 ** 12


class Invalid(Exception):
    """Raised for any schema or wire-format violation."""


def _object_pairs(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise Invalid('duplicate key')
        obj[key] = value
    return obj


def _parse_constant(_name):
    raise Invalid('nonfinite constant')


def _is_int(value):
    return type(value) is int


def _check_int(value, low, high, what):
    if not _is_int(value):
        raise Invalid('%s not integer' % what)
    if value < low or value > high:
        raise Invalid('%s out of range' % what)
    return value


def _check_list(value, low, high, what):
    if type(value) is not list:
        raise Invalid('%s not list' % what)
    if len(value) < low or len(value) > high:
        raise Invalid('%s length out of range' % what)
    return value


def parse_request(raw):
    """Decode and structurally validate the raw request bytes."""
    if len(raw) > MAX_BYTES:
        raise Invalid('too large')
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise Invalid('not utf-8')
    decoder = json.JSONDecoder(object_pairs_hook=_object_pairs,
                               parse_constant=_parse_constant)
    start = 0
    length = len(text)
    while start < length and text[start] in ' \t\n\r':
        start += 1
    try:
        value, end = decoder.raw_decode(text, start)
    except Invalid:
        raise
    except RecursionError:
        raise Invalid('nesting too deep')
    except (ValueError, MemoryError, OverflowError):
        raise Invalid('bad json')
    rest = text[end:]
    if rest.strip():
        raise Invalid('trailing content')
    return value


def _check_depth(value):
    """Iterative container-depth guard (depth over 64 is rejected)."""
    stack = [(value, 1)]
    while stack:
        item, depth = stack.pop()
        if depth > MAX_DEPTH:
            raise Invalid('depth over 64')
        if type(item) is list:
            for sub in item:
                if type(sub) in (list, dict):
                    stack.append((sub, depth + 1))
        elif type(item) is dict:
            for sub in item.values():
                if type(sub) in (list, dict):
                    stack.append((sub, depth + 1))


def _validate_case(case):
    if type(case) is not dict:
        raise Invalid('case not object')
    if set(case.keys()) != {'model', 'class_values', 'stats', 'bucket',
                            'slots', 'flows', 'groups', 'windows'}:
        raise Invalid('case keys')

    model = case['model']
    if type(model) is not str or model not in ('cnn', 'rnn'):
        raise Invalid('model')

    values = case['class_values']
    _check_list(values, 7, 7, 'class_values')
    for value in values:
        _check_int(value, 1, 1000, 'class value')

    stats = case['stats']
    _check_list(stats, 3, 3, 'stats')
    for value in stats:
        _check_int(value, 1, 10 ** 9, 'stats')

    bucket = case['bucket']
    _check_list(bucket, 2, 2, 'bucket')
    _check_int(bucket[0], 1, 512, 'bucket capacity')
    _check_int(bucket[1], 0, bucket[0], 'bucket initial')

    slots = case['slots']
    _check_list(slots, 1, 256, 'slots')
    previous = None
    for slot in slots:
        _check_list(slot, 3, 3, 'slot')
        _check_int(slot[0], 0, INT10_12, 'slot time')
        _check_int(slot[1], 0, 512, 'slot capacity')
        _check_int(slot[2], 0, 512, 'slot refill')
        if previous is not None and slot[0] <= previous:
            raise Invalid('slot times not increasing')
        previous = slot[0]
    if slots[0][2] != 0:
        raise Invalid('first refill not zero')

    flows = case['flows']
    _check_list(flows, 1, 32, 'flows')
    groups = case['groups']
    _check_list(groups, 0, 32, 'groups')

    for flow in flows:
        _check_list(flow, 4, 4, 'flow')
        _check_int(flow[0], 1, 64, 'flow target')
        _check_int(flow[1], flow[0], 512, 'flow ceiling')
        _check_int(flow[2], -1, len(groups) - 1, 'flow group')
        _check_int(flow[3], 0, 6, 'flow label')

    for group in groups:
        _check_list(group, 2, 2, 'group')
        _check_int(group[0], -1, len(groups) - 1, 'group parent')
        _check_int(group[1], 0, 512, 'group ceiling')

    for index, group in enumerate(groups):
        # acyclic parent chain
        seen = set()
        node = index
        while node != -1:
            if node in seen:
                raise Invalid('group cycle')
            seen.add(node)
            node = groups[node][0]
        if len(seen) > len(groups):
            raise Invalid('group cycle')

    windows = case['windows']
    _check_list(windows, 0, 512, 'windows')
    for window in windows:
        _check_list(window, 8, 8, 'window')
        _check_int(window[0], 0, len(flows) - 1, 'window flow')
        _check_int(window[1], 0, INT10_12, 'window ready')
        _check_int(window[2], window[1], INT10_12, 'window expires')
        _check_int(window[3], 1, 65535, 'window T')
        _check_int(window[4], 1, 320, 'window C')
        _check_int(window[5], 0, 65535, 'window draw')
        _check_int(window[6], 1, 1000, 'window priority')
        features = window[7]
        _check_list(features, 9, 9, 'features')
        for pair in features:
            _check_list(pair, 2, 2, 'feature')
            _check_int(pair[0], 0, 1500, 'packet length')
            _check_int(pair[1], 0, 2560, 'packet ipd')
    return len(windows)


def validate_request(raw):
    """Return the validated request, or raise Invalid."""
    value = parse_request(raw)
    if type(value) is not dict:
        raise Invalid('top level not object')
    if set(value.keys()) != {'version', 'cases'}:
        raise Invalid('top level keys')
    if not _is_int(value['version']) or value['version'] != 3:
        raise Invalid('version')
    cases = value['cases']
    if type(cases) is not list:
        raise Invalid('cases not list')
    if len(cases) > 8:
        raise Invalid('too many cases')
    total = 0
    for case in cases:
        total += _validate_case(case)
    if total > 1024:
        raise Invalid('too many windows')
    _check_depth(value)
    return value
